    "pt-BR": "Cada idioma lê os nomes de um jeito, então isto pode não corresponder ao som do seu.",
    fr: "Les noms se prononcent différemment selon la langue ; cette écriture peut donc ne pas correspondre à la vôtre.",
    de: "Namen werden je nach Sprache anders gelesen, daher kann diese Schreibung von Ihrer Aussprache abweichen.",
    it: "I nomi si leggono in modo diverso da una lingua all'altra, quindi questa grafia potrebbe non corrispondere alla tua.",
