    km: "ឈ្មោះត្រូវបានអានខុសៗគ្នាតាមភាសានីមួយៗ ដូច្នេះការសរសេរនេះអាចមិនត្រូវនឹងសំឡេងឈ្មោះរបស់អ្នកទេ។",
